package com.universe.community.controller; import com.universe.community.dto.response.PostLikeResponse; import com.universe.community.service.PostLikeService; import com.universe.global.common.ApiResponse; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequiredArgsConstructor public class PostLikeController {private final PostLikeService service; @PostMapping("/api/v1/community/posts/{postId}/likes") public ApiResponse<PostLikeResponse> like(@PathVariable Long postId){return ApiResponse.success(service.like(postId));} @DeleteMapping("/api/v1/community/posts/{postId}/likes") public ApiResponse<PostLikeResponse> unlike(@PathVariable Long postId){return ApiResponse.success(service.unlike(postId));}}
